/** Resolves a semantic name to its literal colour string in a theme. */
export function resolveColor(name: string, theme: keyof typeof themes = 'dark'): string {
  const map: Record<string, string> = { ...themes[theme] };
  const value = map[name] ?? name;
  const palette = tokens.palette as Record<string, string>;
  return palette[value] ?? value;
}

function block(selector: string, lines: string[]): string {
  return `${selector} {\n${lines.map((l) => `  ${l}`).join('\n')}\n}\n`;
}

/**
 * Renders src/app/tokens.css. Palette and semantic aliases go inside @theme so
 * Tailwind emits utilities (bg-surface, text-led-text, ease-light…); the paper
 * and sepia layers re-point the semantic variables on a scope.
 */
export function renderTokensCss(): string {
  const theme: string[] = [];
  theme.push('/* palette */');
  for (const [k, v] of Object.entries(tokens.palette)) theme.push(`--color-${k}: ${v};`);
  theme.push('', '/* semantic (dark) */');
  for (const [k, v] of Object.entries(themes.dark)) {
    const ref = v in tokens.palette ? `var(--color-${v})` : v;
    theme.push(`--color-${k}: ${ref};`);
  }
  theme.push('', '/* type */');
  for (const [k, v] of Object.entries(tokens.font)) theme.push(`--font-${k}: ${v};`);
  for (const [k, v] of Object.entries(tokens.text)) theme.push(`--text-${k}: ${v};`);
  for (const [k, v] of Object.entries(tokens.tracking)) theme.push(`--tracking-${k}: ${v};`);
  theme.push('', '/* motion */');
  for (const [k, v] of Object.entries(tokens.ease)) theme.push(`--ease-${k}: ${v};`);
  for (const [k, v] of Object.entries(tokens.dur)) theme.push(`--dur-${k}: ${v};`);
  theme.push('', '/* shape & layout */');
  for (const [k, v] of Object.entries(tokens.radius)) theme.push(`--radius-${k}: ${v};`);
  for (const [k, v] of Object.entries(tokens.layout)) theme.push(`--${k}: ${v};`);

  const scoped = (name: 'paper' | 'sepia', scheme: 'light' | 'dark') => {
    const lines: string[] = [];
    for (const [k, v] of Object.entries(themes[name])) {
      const ref = v in tokens.palette ? `var(--color-${v})` : v;
      lines.push(`--color-${k}: ${ref};`);
    }
    lines.push(`color-scheme: ${scheme};`);
    return block(`[data-theme='${name}']`, lines);
  };

  return [
    '/* src/app/tokens.css',
    '   GENERATED by scripts/generate-tokens.mjs from src/design/tokens.ts.',
    '   Do not edit by hand: change tokens.ts and run `npm run tokens`. */',
    '',
    block('@theme', theme),
    scoped('paper', 'light'),
    scoped('sepia', 'dark'),
  ].join('\n');
}
